#!/usr/bin/env node
// wugweb-brand-os: build.mjs
// Builds the portable files from the skill folder and the home standing-rules file,
// so agents other than Claude can load the skill. Never edit the outputs by hand.
//
//   node scripts/build.mjs           write the generated files
//   node scripts/build.mjs --check   exit 1 if any generated file is stale
//
// Sources: SKILL.md, references/*.md, references/visual-os/*.md, examples/*.md,
// docs/skills/STANDING-RULES.md, metadata.json.
// Outputs: AGENTS.md, export/wugweb-brand-os.md, adapters/cursor/wugweb-brand-os.mdc,
// adapters/chatgpt/instructions.md, agents/openai.yaml.
// Plain Node 18 or later. No packages. No network.

import { readFileSync, writeFileSync, mkdirSync, readdirSync, statSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

export const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
export const HOME_RULES = join(ROOT, '..', '..', '..', 'docs', 'skills', 'STANDING-RULES.md');
const read = (p) => readFileSync(join(ROOT, p), 'utf8');

const listMd = (dir) => {
  const abs = join(ROOT, dir);
  if (!existsSync(abs)) return [];
  return readdirSync(abs)
    .sort()
    .filter((f) => f.endsWith('.md') && !statSync(join(abs, f)).isDirectory())
    .map((f) => `${dir}/${f}`);
};

export function sources() {
  const skill = read('SKILL.md');
  const front = skill.match(/^---\n([\s\S]*?)\n---\n/);
  if (!front) throw new Error('SKILL.md has no frontmatter');
  const name = (front[1].match(/^name:\s*(\S+)\s*$/m) || [])[1];
  const descRaw = (front[1].match(/^description:\s*(".*")\s*$/m) || [])[1];
  if (!name || !descRaw) throw new Error('SKILL.md frontmatter needs name and a double-quoted description');
  const description = JSON.parse(descRaw);
  const version = (front[1].match(/version:\s*"([^"]+)"/) || [])[1] || 'unknown';
  const body = skill.slice(front[0].length).trim();
  const files = [...listMd('references'), ...listMd('references/visual-os'), ...listMd('examples')];
  const refs = files.map((f) => `\n\n---\n\n<!-- ${f} -->\n\n${read(f).trim()}`).join('');
  const rules = existsSync(HOME_RULES) ? readFileSync(HOME_RULES, 'utf8').replace(/^# .*\n+/, '').trim() : null;
  return { name, description, version, body, files, refs, rules };
}

export function outputs() {
  const { name, description, version, body, refs, rules } = sources();
  if (rules === null) throw new Error('docs/skills/STANDING-RULES.md not found; the generated files must carry the standing rules');

  const rulesBlock = [
    "## Owner's standing rules",
    '',
    'Copied from `docs/skills/STANDING-RULES.md`. That file is the source; if this block differs, that file wins.',
    '',
    rules,
  ].join('\n');

  // AGENTS.md: the whole skill in one file, with the standing-rules block, for
  // agents that read AGENTS.md or take one knowledge file.
  const agents = [
    `# ${name} (single-file export for other tools, v${version})`,
    '',
    'Built from the files in this folder by `scripts/build.mjs`. Do not edit by hand. Rebuild whenever the skill or `docs/skills/STANDING-RULES.md` changes. Read the skill first, then the reference a mode names.',
    '',
    rulesBlock,
    '',
    '---',
    '',
    body,
    refs,
    '',
  ].join('\n');

  // export/wugweb-brand-os.md: the same content under the skill's own name, to
  // paste or attach where a file called AGENTS.md would be read as project rules.
  const exp = agents.replace(
    `# ${name} (single-file export for other tools, v${version})`,
    `# ${name} (single-file export, v${version})`,
  );

  // Cursor rule. Attaches by description, not always on.
  const cursor = [
    '---',
    `description: ${JSON.stringify(description)}`,
    `globs: ["**/skills/${name}/**", "docs/skills/${name}/**", "brand_guidelines/**"]`,
    'alwaysApply: false',
    '---',
    '',
    '<!-- Generated by scripts/build.mjs. Do not edit by hand. -->',
    '',
    body,
    '',
  ].join('\n');

  // Custom GPT or ChatGPT project instructions.
  const chatgpt = [
    '<!-- Generated by scripts/build.mjs. Do not edit by hand. -->',
    '',
    '# Instructions for a custom GPT or project',
    '',
    'Paste the block below into the instructions field. Upload `AGENTS.md` from this skill as a knowledge file.',
    '',
    '```',
    "You answer questions about who Wugweb is and check whether visuals and claims",
    "are on brand, using the uploaded file AGENTS.md. Read AGENTS.md before any",
    "question about Wugweb's positioning, values, audience, messaging, approved",
    "facts, brand rules or how a card, slide or cover should look. Name the mode at",
    "the top of the reply: Answer, Visual check, Fact check or Change.",
    '',
    'Always:',
    '- Cite the reference file behind every answer.',
    '- Report a gap as "not decided: the owner decides". Never fill it.',
    '- Mark each claim about Wugweb approved or not approved, as brand-facts.md',
    '  records it. Never soften, round or replace a number.',
    '- Show any change as current then proposed, and apply nothing until the owner',
    '  says yes.',
    '- Apply the fixed owner rules: British English, sentence case, no em or en',
    '  dashes, never invent a number quote or fact, result first.',
    '',
    'Never:',
    '- Write or rewrite copy, or make, crop or re-encode media (that is',
    '  wugweb-work).',
    '- Hold or check voice and tone rules (that is wugweb-voice).',
    '- Give a token value, component or layout (that is wugweb-kits).',
    "- Touch a client's brand, which stays with its case study.",
    '- Write to Notion, Sanity or R2, or edit brand_guidelines/.',
    '```',
    '',
  ].join('\n');

  // Display settings for Codex and the ChatGPT desktop app. Other agents ignore it.
  const openai = [
    '# Generated by scripts/build.mjs. Do not edit by hand.',
    '# Display settings for Codex and the ChatGPT desktop app. Other agents ignore this file.',
    'interface:',
    `  display_name: "${name}"`,
    '  short_description: "Who Wugweb is, and whether a visual or claim is on brand"',
    `  default_prompt: "Using ${name}, check whether this artwork brief is on brand."`,
    'policy:',
    '  allow_implicit_invocation: true',
    '',
  ].join('\n');

  return {
    'AGENTS.md': agents,
    [`export/${name}.md`]: exp,
    [`adapters/cursor/${name}.mdc`]: cursor,
    'adapters/chatgpt/instructions.md': chatgpt,
    'agents/openai.yaml': openai,
  };
}

const isMain = process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1];
if (isMain) {
  const checkOnly = process.argv.includes('--check');
  let stale = 0;
  for (const [rel, content] of Object.entries(outputs())) {
    const full = join(ROOT, rel);
    if (checkOnly) {
      const ok = existsSync(full) && readFileSync(full, 'utf8') === content;
      console.log(`${ok ? 'fresh' : 'STALE'}  ${rel}`);
      if (!ok) stale++;
    } else {
      mkdirSync(dirname(full), { recursive: true });
      writeFileSync(full, content);
      console.log(`wrote  ${rel}`);
    }
  }
  if (!checkOnly) console.log(`built v${sources().version}`);
  process.exit(stale ? 1 : 0);
}
